  if(n===6)p.gearArea=(p.gearArea||0)+v/100;if(n===13)p.maxhp+=v;if(n===14)p.armor=(p.armor||0)+v;
  if(n===15)p.regen=(p.regen||0)+v/10;if(n===16)p.lifeOnKill=(p.lifeOnKill||0)+v;
