    // ปุ่มรีเซ็ต perk (คืนแต้มทั้งหมด) · B15 + B16
    const ry2=this.tuHas('perk_reset_btn')?y:Math.min(h-42,y),rw=Math.min(w-40,300),rp=this.tuPanel('perk_reset_btn',this._perkResetConfirm?1:0,w/2-rw/2,ry2,rw,34);
