    const ensure=()=>{ if(live(hl))return; hl=this.add.graphics(); this.menu.add(hl); pins.forEach(pn=>{ if(!pn.objs||!live(pn.objs[0]))drawPin(pn); }); this.menu.bringToTop(hl); };
