        this.hudVisible(true);
        this.elapsed=0; this.kills=0; this.stageKills=0; this.sugarStage=0; this.sugarRun=0; if(this.runSugarTxt)this.runSugarTxt.setText('🍬 0');
        if(this.killTxt)this.killTxt.setText('☠ 0');
