    box.push(this.add.text(w/2,py+ph*.709,curKeys.length?'Currency Gained':'No currency this run',{fontFamily:'sans-serif',fontStyle:'bold',fontSize:(font-1)+'px',color:'#ffe9bc'}).setOrigin(.5));
