        b.dmg*=.45*(basic.evolved?1.35:1);b.life=.3;b.sgPellet=true;b.closeMul=.4+.15*(basic.ranks.pointblank||0)+(PT.close||0);b.cqMul=PT.cq||0;b.knockback=110+(PT.kb||0)*60;b.dragon=!!PT.dragon;
