    b.headshot=.07*(b0.ranks.headshot||0)+(PT.hs||0);b.bigMul=.15*(b0.ranks.deadeye||0)+(PT.big||0);b.penGain=PT.pen||0;b.oneShot=!!PT.oneShot;b._ptSniper=true;
