    g.clear();g.fillStyle(0x2c2038,1);g.fillRoundedRect(cx-cardW/2,cy-cardH/2,cardW,cardH,18);g.lineStyle(5,col,1);g.strokeRoundedRect(cx-cardW/2,cy-cardH/2,cardW,cardH,18);
