    if(ASSET_SHEETS[key]&&ASSET_SHEETS[key].actions){const state=frame===6?'hurt':base==='e_crown_ripper'?(frame===4?'windup':'dash'):base==='e_banquet_eye'?'attack':frame===4?'windup':'attack';this.enemyAction(e,state,ms);return;}
