      fog.fillStyle(color,al); fog.fillRect(W.x-60,W.y-60,W.w+120,W.h+120); fog.fillStyle(0xeafff2,.22); for(const q of B){ fog.fillCircle(q.x,q.y,q.r); fog.lineStyle(4,0xbfffe0,.9).strokeCircle(q.x,q.y,q.r); }
